#include <iostream>
#include <vector>
int main() {
    std::vector<int> nums{2, 4, 6};
    int total = 0;
    for (int value : nums) {
        total += value;
    }
    std::cout << total << '\n';
}

#include <iostream>
#include <vector>
int sum(const std::vector<int>& nums) {
    int total = 0;
    for (int x : nums) total += x;
    return total;
}
int main() {
    std::cout << sum({2, 3}) << '\n';
}

